        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            current_spy_sma = self.spy_sma.Current.Value

            if self.previous_spy_close is not None:
                spy_cross_up = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_bar.Close > current_spy_sma
                )
                spy_cross_down = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_bar.Close < current_spy_sma
                )
            else:
                spy_cross_up = False
                spy_cross_down = False

            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_spy_sma
        else:
            spy_cross_up = False
            spy_cross_down = False

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close

            aapl_rsi_ready = self.aapl_rsi.IsReady
            aapl_rsi_above_60 = aapl_rsi_ready and self.aapl_rsi.Current.Value > 60
        else:
            aapl_rsi_above_60 = False

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.all_symbols):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        if self.spy_sma.IsReady and self.strategy_a_lot > 0 and spy_cross_down:
            self._submit_order(
                self.spy,
                -self.strategy_a_lot,
                "Strategy A Sell"
