        if self.aapl_rsi.IsReady and self.strategy_b_lot > 0 and aapl_rsi_above_60:
            self._submit_order(
                self.aapl,
                -self.strategy_b_lot,
                "Strategy B Sell"
            )

        if self.spy_sma.IsReady and self.strategy_a_lot == 0 and spy_cross_up:
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue))
                / float(spy_bar.Close)
