                quantity = int(20000 / float(aapl_bar.Close))
                if quantity > 0:
                    self._submit_order(self.aapl, quantity, "Strategy B Buy")

    def _submit_order(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        self.order_strategy[ticket.OrderId] = tag

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.FillQuantity == 0:
            return

        tag = self.order_strategy.get(order_event.OrderId)
        if tag is None:
            return

        if tag.startswith("Strategy A"):
            self.strategy_a_lot += int(order_event.FillQuantity)
            if self.strategy_a_lot < 0:
                self.strategy_a_lot = 0

        elif tag.startswith("Strategy B"):
            self.strategy_b_lot += int(order_event.FillQuantity)
