                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_values = deque(maxlen=self.rsi_period + 1)
        self.aapl_rsi = None
        self.aapl_rsi_average_gain = None
        self.aapl_rsi_average_loss = None

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = set()

    def OnData(self, data):
        self._update_market_state(data)

        required_symbols = list(self.symbols.values())
        if any(symbol not in data.Bars for symbol in required_symbols):
            return

        if len(self.spy_closes) < 101:
            return

        spy_buy_signal, spy_sell_signal = self._spy_cross_signals()
        aapl_buy_signal = self.aapl_red_streak >= 3
        aapl_sell_signal = (
            self.aapl_rsi is not None and self.aapl_rsi > 60
        )

        # Sell before buy.
        if self.lots["A"] > 0 and spy_sell_signal:
            self._sell_lot("A", "SPY")

        if self.lots["B"] > 0 and aapl_sell_signal:
            self._sell_lot("B", "AAPL")

        # Buy only while the strategy's lot is empty.
        if self.lots["A"] == 0 and spy_buy_signal:
            close = data.Bars[self.symbols["SPY"]].Close
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value / close)

            if quantity > 0:
                self._buy_lot("A", "SPY", quantity)

        if self.lots["B"] == 0 and aapl_buy_signal:
            close = data.Bars[self.symbols["AAPL"]].Close

            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / close)

                if quantity > 0:
                    self._buy_lot("B", "AAPL", quantity)

    def _update_market_state(self, data):
        spy = self.symbols["SPY"]
        if spy in data.Bars:
            self.spy_closes.append(float(data.Bars[spy].Close))

        aapl = self.symbols["AAPL"]
        if aapl not in data.Bars:
            return

        close = float(data.Bars[aapl].Close)

        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self._update_rsi(close)

        self.aapl_previous_close = close

    def _update_rsi(self, close):
        self.rsi_values.append(close)

        if len(self.rsi_values) < self.rsi_period + 1:
            return

        previous = self.rsi_values[-2]
        change = close - previous
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_rsi_average_gain is None:
            gains = []
            losses = []

            for i in range(1, len(self.rsi_values)):
                delta = self.rsi_values[i] - self.rsi_values[i - 1]
                gains.append(max(delta, 0.0))
                losses.append(max(-delta, 0.0))

            self.aapl_rsi_average_gain = sum(gains) / self.rsi_period
            self.aapl_rsi_average_loss = sum(losses) / self.rsi_period
        else:
            self.aapl_rsi_average_gain = (
                (self.aapl_rsi_average_gain * (self.rsi_period - 1)) + gain
            ) / self.rsi_period

            self.aapl_rsi_average_loss = (
                (self.aapl_rsi_average_loss * (self.rsi_period - 1)) + loss
            ) / self.rsi_period

        if self.aapl_rsi_average_loss == 0:
            self.aapl_rsi = 100.0
        else:
            relative_strength = (
                self.aapl_rsi_average_gain /
                self.aapl_rsi_average_loss
            )
            self.aapl_rsi = 100.0 - (
                100.0 / (1.0 + relative_strength)
            )

    def _spy_cross_signals(self):
        previous_close = self.spy_closes[-2]
        current_close = self.spy_closes[-1]

        previous_sma = sum(list(self.spy_closes)[:-1]) / 100.0
        current_sma = sum(list(self.spy_closes)[1:]) / 100.0

        crossed_up = (
            previous_close <= previous_sma and
            current_close > current_sma
        )

        crossed_down = (
            previous_close >= previous_sma and
            current_close < current_sma
        )

        return crossed_up, crossed_down

    def _buy_lot(self, lot_id, ticker, quantity):
        if lot_id in self.pending_orders:
            return

        symbol = self.symbols[ticker]
        self.pending_orders.add(lot_id)
        self.MarketOrder(symbol, quantity, tag=f"{lot_id}_BUY")

    def _sell_lot(self, lot_id, ticker):
        if lot_id in self.pending_orders:
            return

        shares = self.lots[lot_id]
        if shares <= 0:
            return

        quantity = shares
        symbol = self.symbols[ticker]

        self.pending_orders.add(lot_id)
        self.MarketOrder(symbol, -quantity, tag=f"{lot_id}_SELL")

    def OnOrderEvent(self, orderEvent):
        if orderEvent.FillQuantity == 0:
            return

        order = self.Transactions.GetOrderById(orderEvent.OrderId)
        tag = order.Tag

        if tag == "A_BUY":
            self.lots["A"] += orderEvent.FillQuantity
        elif tag == "A_SELL":
            self.lots["A"] += orderEvent.FillQuantity
        elif tag == "B_BUY":
            self.lots["B"] += orderEvent.FillQuantity
        elif tag == "B_SELL":
            self.lots["B"] += orderEvent.FillQuantity

        if orderEvent.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if tag.startswith("A_"):
                self.pending_orders.discard("A")
            elif tag.startswith("B_"):
                self.pending_orders.discard("B")

        self.lots["A"] = max(0, self.lots["A"])
        self.lots["B"] = max(0, self.lots["B"])

